package com.primehr.evidence.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="evidence_assessment_event")public class EvidenceAssessmentEvent extends RspAuditedEntity{@Column(name="assessment_case_id",nullable=false,length=36)private String assessmentCaseId;@Column(name="aggregate_type",nullable=false,length=40)private String aggregateType;@Column(name="aggregate_id",nullable=false,length=36)private String aggregateId;@Column(name="event_type",nullable=false,length=60)private String eventType;@Column(name="actor_employee_no",nullable=false,length=100)private String actorEmployeeNo;@Column(length=3000)private String reason;@Column(name="from_status",length=40)private String fromStatus;@Column(name="to_status",length=40)private String toStatus;@Column(name="event_at",nullable=false)private Instant eventAt;protected EvidenceAssessmentEvent(){}public EvidenceAssessmentEvent(String a,String c,String aggregate,String aggregateId,String event,String actor,String reason,String from,String to,Instant at){super(a);assessmentCaseId=requiredText(c,"assessmentCaseId");aggregateType=requiredText(aggregate,"aggregateType");this.aggregateId=requiredText(aggregateId,"aggregateId");eventType=requiredText(event,"eventType");actorEmployeeNo=requiredText(actor,"actor");this.reason=optionalText(reason);fromStatus=optionalText(from);toStatus=optionalText(to);eventAt=at;}public String getAssessmentCaseId(){return assessmentCaseId;}public String getAggregateType(){return aggregateType;}public String getAggregateId(){return aggregateId;}public String getEventType(){return eventType;}public String getActorEmployeeNo(){return actorEmployeeNo;}public String getReason(){return reason;}public String getFromStatus(){return fromStatus;}public String getToStatus(){return toStatus;}public Instant getEventAt(){return eventAt;}}
